// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 timestampIncrease, uint256 msgValue) public {
        // Ensure msg.value is exactly 10 ether for each call
        vm.assume(msgValue == 10 ether);

        // Warp to a time after pastBlockTime (starting at 0)
        vm.warp(block.timestamp + timestampIncrease + 1);

        // Make the fallback call
        (bool success, ) = address(c).call{value: msgValue}("");

        // Assert that either the call reverted or pastBlockTime is strictly less than the next block.timestamp
        // This is a general rule: the reference ensures pastBlockTime = block.timestamp + 1 after a successful call,
        // so pastBlockTime < block.timestamp in any later block. The bug sets pastBlockTime = block.timestamp,
        // which allows equality and breaks the strict inequality requirement.
        uint256 currentTime = block.timestamp;
        assertTrue(!success || c.pastBlockTime() < currentTime);
    }
}

