pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint _callerSeed) public {
        address caller = address(uint160(bound(_callerSeed, 1, type(uint160).max)));
        vm.deal(caller, 20 ether);

        // First call (reference requires block.timestamp > pastBlockTime which is 0 at start)
        vm.prank(caller);
        (bool success1,) = address(c).call{value: 10 ether}("");

        // Advance time to ensure second call can succeed
        vm.warp(block.timestamp + 2);

        // Record state after first call
        uint pastBlockTimeAfterFirst = c.pastBlockTime();

        // Second call
        vm.prank(caller);
        (bool success2,) = address(c).call{value: 10 ether}("");

        // After second call, pastBlockTime should be > block.timestamp at time of previous call
        // In correct version: pastBlockTime = block.timestamp + 1 after both calls
        // In mutant: pastBlockTime is only updated if block.number % 15 == 0 at the end
        // So for correct: pastBlockTimeAfterSecond = block.timestamp_of_second + 1 > block.timestamp_of_first + 1 = pastBlockTimeAfterFirst
        // But since both happen in same block? Actually we warped so block.timestamp differs.
        // General rule: pastBlockTime is monotonically increasing (strictly) with each succeeded call
        uint pastBlockTimeAfterSecond = c.pastBlockTime();
        assertTrue(pastBlockTimeAfterSecond > pastBlockTimeAfterFirst);
    }
}

