import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint blockNumber) public {
        vm.assume(caller != address(0));
        vm.assume(blockNumber % 15 == 0);
        vm.roll(blockNumber);

        uint balanceBefore = address(c).balance;
        vm.deal(address(this), 10 ether);
        vm.deal(caller, 1 ether);

        // Call fallback with 10 ether from this contract (reference compliant)
        (bool success1, ) = address(c).call{value: 10 ether}("");
        // Call fallback with 1 ether from caller
        vm.prank(caller);
        (bool success2, ) = address(c).call{value: 1 ether}("");

        // The rule: if block.number % 15 == 0 and caller sends 1 ether, the contract should NOT transfer its balance (only the 10 ether call should trigger transfer)
        // After the 10 ether call, contract balance becomes 10 ether; then 1 ether call should revert if block.timestamp condition satisfied
        // But the mutant allows 1 ether call to succeed and trigger transfer
        // So we assert that the contract balance after both calls is 10 ether (only the 1 ether was added, no transfer)
        assertTrue(address(c).balance == 10 ether || (!success1 && address(c).balance == 1 ether));
    }
}

