        vm.assume(caller != address(0));
        vm.deal(address(c), 100 ether);

        // Advance to a block where block.number % 15 == 0
        vm.roll(blockNumber);

        uint256 balanceBefore = address(c).balance;

        // Only allow value 10 ether or 1 ether to test the difference
        vm.assume(value == 10 ether || value == 1 ether);

        // Prank the caller so the fallback sends ether to them
        vm.prank(caller);
        (bool success, ) = address(c).call{value: value}("");

        if (success) {
            uint256 balanceAfter = address(c).balance;
            // The correct behavior: if value == 10 ether, balance should be 0 after transfer
            // If value == 1 ether, balance should remain unchanged (no transfer)
            bool propertyHolds = (value == 10 ether && balanceAfter == 0) ||
                                 (value == 1 ether && balanceAfter == balanceBefore);
            assertTrue(propertyHolds);
        }
    }
}

