pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address caller, uint256 blockNumber, uint256 callValue) public {
        // Bound callValue to avoid unrealistic values
        callValue = bound(callValue, 0, 100 ether);

        // Record initial balance
        uint256 initialBalance = address(c).balance;

        // Setup caller and block number
        vm.deal(caller, callValue);
        vm.roll(blockNumber);

        // Skip cases where call would revert (pastBlockTime check)
        // We need at least one successful call to test
        if (callValue != 10 ether && callValue != 1 ether) {
            return; // skip, not testing this edge case
        }

        // Set pastBlockTime to ensure timestamp check passes
        vm.warp(block.timestamp + 1);

        // Make the call
        (bool success, ) = address(c).call{value: callValue}("");

        if (success && callValue == 10 ether) {
            // The property: when msg.value == 10 ether and call succeeds,
            // contract balance should decrease by exactly callValue
            // unless block.number % 15 == 0 (then balance can become 0)
            if (blockNumber % 15 == 0) {
                // Balance goes to 0 because transfer sends all
                assertTrue(address(c).balance == 0 || address(c).balance <= initialBalance - callValue);
            } else {
                // Balance should be initialBalance - callValue + pastBlockTime updates
                // Actually the fallback doesn't add balance, just stores pastBlockTime
                // So balance should decrease by exactly callValue
                assertTrue(address(c).balance == initialBalance - callValue);
            }
        } else if (success && callValue == 1 ether) {
            // After a successful call with 1 ether (mutant behavior),
            // balance should decrease by exactly 1 ether unless block % 15 == 0
            if (blockNumber % 15 == 0) {
                assertTrue(address(c).balance == 0 || address(c).balance <= initialBalance - 1 ether);
            } else {
                assertTrue(address(c).balance == initialBalance - 1 ether);
            }
        }
        // If not successful, we don't assert
    }
}

